package run.ikaros.music;
import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; import run.ikaros.storage.AttachmentRepository;
@Service public class PersistentMusicAudioSourceService implements MusicAudioSourceService {private final MusicTrackRepository tracks;private final MusicAudioSourceRepository sources;private final AttachmentRepository attachments;public PersistentMusicAudioSourceService(MusicTrackRepository t,MusicAudioSourceRepository s,AttachmentRepository a){tracks=t;sources=s;attachments=a;}
 @Override public Mono<MusicAudioSourceView> add(UUID owner,UUID trackId,AddMusicAudioSourceRequest r){return ownedTrack(owner,trackId).flatMap(t->attachments.findByIdAndResourceIdAndDeletedAtIsNull(r.attachmentId(),t.resourceId()).switchIfEmpty(Mono.error(new NotFoundException("Audio Attachment 不属于该 Track Resource"))).flatMap(a->sources.save(new MusicAudioSourceEntity(null,owner,trackId,a.id(),r.codec(),r.container(),r.durationMillis(),r.sampleRate(),r.bitDepth(),r.channels(),r.bitrate(),r.lossless(),"AVAILABLE",r.preferenceWeight(),null)))).map(this::view);}
 @Override public Flux<MusicAudioSourceView> list(UUID owner,UUID trackId){return ownedTrack(owner,trackId).flatMapMany(t->sources.findAllByOwnerIdAndTrackIdOrderByPreferenceWeightDesc(owner,trackId).map(this::view));}
 @Override public Mono<MusicAudioSourceView> resolve(UUID owner,UUID trackId,UUID sourceId){return ownedTrack(owner,trackId).then(sourceId==null?sources.findAllByOwnerIdAndTrackIdOrderByPreferenceWeightDesc(owner,trackId).filter(s->"AVAILABLE".equals(s.availability())).next():sources.findById(sourceId).filter(s->s.ownerId().equals(owner)&&s.trackId().equals(trackId)&&"AVAILABLE".equals(s.availability()))).switchIfEmpty(Mono.error(new NotFoundException("没有可用的 Audio Source"))).map(this::view);}
 private Mono<MusicTrackEntity> ownedTrack(UUID o,UUID id){return tracks.findById(id).filter(t->t.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("Track 不存在或无权访问")));}private MusicAudioSourceView view(MusicAudioSourceEntity e){return new MusicAudioSourceView(e.id(),e.trackId(),e.attachmentId(),e.codec(),e.container(),e.durationMillis(),e.sampleRate(),e.bitDepth(),e.channels(),e.bitrate(),e.lossless(),e.availability(),e.preferenceWeight());}}
